def solve(grid):
    import copy
    result = copy.deepcopy(grid)
    rows, cols = len(grid), len(grid[0])
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 5:
                result[r][c] = 8
            elif grid[r][c] == 8:
                result[r][c] = 5
    return result
